Manual tokenizer:

We have `inner` slice. We can iterate over it with an index `i`.

```zig
var i: usize = 0;
var expecting_operand = true;
var pending_op: ?Op = null;
var result: i32 = 0;

while (i < inner.len) {
    // skip spaces
    while (i < inner.len and inner[i] == ' ') i += 1;
    if (i >= inner.len) break;

    // find end of word
    const start = i;
    while (i < inner.len and inner[i] != ' ') i += 1;
    const word = inner[start..i];

    // parse word
    const op = blk: {
        if (std.mem.eql(u8, word, "plus")) {
            break :blk .plus;
        } else if (std.mem.eql(u8, word, "minus")) {
            break :blk .minus;
        } else if (std.mem.eql(u8, word, "multiplied")) {
            // peek next word
            // skip spaces
            const peek_start = i;
            while (i < inner.len and inner[i] == ' ') i += 1;
            if (i >= inner.len) return ArgumentError.UnsupportedQuestion;
            const peek_start2 = i;
            while (i < inner.len and inner[i] != ' ') i += 1;
            const next_word = inner[peek_start2..i];
            if (!std.mem.eql(u8, next_word, "by")) return ArgumentError.UnsupportedQuestion;
            break :blk .multiplied_by;
        } else if (std.mem.eql(u8, word, "divided")) {
            const peek_start = i;
            while (i < inner.len and inner[i] == ' ') i += 1;
            if (i >= inner.len) return ArgumentError.UnsupportedQuestion;
            const peek_start2 = i;
            while (i < inner.len and inner[i] != ' ') i += 1;
            const next_word = inner[peek_start2..i];
            if (!std.mem.eql(u8, next_word, "by")) return ArgumentError.UnsupportedQuestion;
            break :blk .divided_by;
        } else {
            // number
            const num = std.fmt.parseInt(i32, word, 10) catch {
                return ArgumentError.UnsupportedQuestion;
            };
            // handle number
            if (!expecting_operand) return ArgumentError.SyntaxError;
            if (pending_op) |op| {
                result = apply(op, result, num) catch |err| {
                    if (err == ArgumentError.DivisionByZero) return err;
                    return err;
                };
                pending_op = null;
            } else {
                result = num;
            }
            expecting_operand = false;
            continue;
        }
    };

    // handle operator
    if (expecting_operand) return ArgumentError.SyntaxError;
    pending_op = op;
    expecting_operand = true;
}

if (expecting_operand) return ArgumentError.SyntaxError;
return result;
```

This avoids allocation entirely. It's a bit more code but cleaner.

